/**
 * The app theme: the preference, how it resolves, and how it reaches the page.
 *
 * LAYOUT_SPEC.md §7 (Theme runtime), decision log C6, implementation plan §4
 * B3. Two consumers share this module so they cannot disagree: the pre-paint
 * script in `index.html` (generated by `themePrePaint.ts`, which runs before
 * React and before first paint) and `ThemeProvider` (which takes over once the
 * app is running).
 *
 * The preference is what the visitor chose: `light`, `dark` or `system`. The
 * resolved theme is what is drawn, always `light` or `dark`. `data-theme` on
 * `<html>` carries the resolved one, which is what every colour token keys on;
 * `data-theme-preference` carries the choice, for anything that needs to
 * know `system` was picked.
 *
 * THE BOARD IS NOT THIS. Its appearance is a separate preference with its own
 * storage key (`boardThemes.ts`), and it keeps its colours in both app themes.
 */
import {
  THEME_STORAGE_KEY,
  parsePreference,
  themeColor,
  type ResolvedTheme,
  type ThemePreference,
} from './themeCore';

export * from './themeCore';

/** Storage can throw (blocked site data, some private modes); a throw is no choice. */
export function readStoredPreference(storage: Pick<Storage, 'getItem'> | undefined = safeLocalStorage()): ThemePreference | null {
  try {
    return parsePreference(storage?.getItem(THEME_STORAGE_KEY));
  } catch {
    return null;
  }
}

export function writeStoredPreference(preference: ThemePreference, storage: Pick<Storage, 'setItem'> | undefined = safeLocalStorage()): void {
  try {
    storage?.setItem(THEME_STORAGE_KEY, preference);
  } catch {
    /* A preference that cannot be saved still applies for this visit. */
  }
}

function safeLocalStorage(): Storage | undefined {
  try {
    return typeof window === 'undefined' ? undefined : window.localStorage;
  } catch {
    return undefined;
  }
}

/**
 * Put a theme on the page. The pre-paint script does the same four things in
 * the same order before React exists; `themePrePaint.test.ts` runs that script
 * and compares the result with this function's.
 *
 * `theme-color` is written on EVERY meta of that name, including the
 * media-keyed ones: those follow the operating system's scheme, so a visitor
 * who picked light on a dark system would otherwise get dark browser chrome
 * over a light page (B0 amendment).
 */
export function applyTheme(root: HTMLElement, preference: ThemePreference, resolved: ResolvedTheme): void {
  root.setAttribute('data-theme', resolved);
  root.setAttribute('data-theme-preference', preference);
  root.style.colorScheme = resolved;
  const color = themeColor(resolved);
  root.ownerDocument.querySelectorAll('meta[name="theme-color"]').forEach((m) => m.setAttribute('content', color));
}
